"""Make the test suite runnable straight from a checkout.

Normally ``jinja2`` is installed (``pip install -e .``) before running the
tests and this file does nothing. When it isn't installed -- a fresh clone, a
container that only mounts the source tree -- fall back to importing the
package from ``src/`` so ``pytest`` still works.

An already importable ``jinja2`` always wins, so this never shadows a
deliberately installed copy.
"""

import importlib.util
import os
import sys

if importlib.util.find_spec("jinja2") is None:
    sys.path.insert(0, os.path.join(os.path.dirname(__file__), "src"))
